package com.yuegang.zhihui.ai.application;
import static org.assertj.core.api.Assertions.*;import com.yuegang.zhihui.ai.api.*;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.ai.infrastructure.CommerceToolGateway;import com.yuegang.zhihui.common.core.BusinessException;import com.yuegang.zhihui.common.test.YghTestContainerFactory;import com.yuegang.zhihui.search.api.SearchHit;import java.time.*;import java.util.*;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import com.fasterxml.jackson.databind.ObjectMapper;
class AiServicesIntegrationTest{@Test void migratesAndSupportsGovernanceSafetyChatHistoryFeedback(){try(var mysql=YghTestContainerFactory.mysql().start()){Flyway.configure().dataSource(mysql.jdbcUrl(),mysql.username(),mysql.credential()).locations("classpath:db/migration").load().migrate();var ds=new DriverManagerDataSource(mysql.jdbcUrl(),mysql.username(),mysql.credential());var governance=new AiGovernanceService(ds);assertThat(governance.activeSystemPrompt()).contains("跨境智汇");var saved=governance.save(new SavePromptConfigRequest("DEFAULT_PROMPT","只依据资料回答","doubao",0.2,"POLICY,CUSTOMS","secret",true,0),9);assertThat(saved.enabled()).isTrue();assertThat(governance.prompts()).hasSize(1);assertThat(governance.activeSystemPrompt()).isEqualTo("只依据资料回答");var safety=new AiSafetyPolicy(ds);assertThatCode(()->safety.guard("通关流程","POLICY")).doesNotThrowAnyException();assertThatThrownBy(()->safety.guard("contains secret","POLICY")).isInstanceOf(BusinessException.class);assertThatThrownBy(()->safety.guard("hello","TRACEABILITY")).isInstanceOf(BusinessException.class);var evidence=new SearchHit("10","20","海关政策","依据",1,OffsetDateTime.parse("2026-07-13T08:00:00Z"),1,1,2);RetrievalGateway retrieval=(q,c,l)->q.contains("无资料")?List.of():List.of(evidence);ModelGateway model=(s,u)->"回答 [10/20]";var tools=new CommerceToolGateway("http://localhost:1","http://localhost:1","01234567890123456789012345678901".getBytes(),new ObjectMapper());var chat=new ChatService(retrieval,model,tools,ds);var response=chat.chat(7,new ChatRequest(null,"跨境政策是什么",null,false));assertThat(response.citations()).hasSize(1);var refused=chat.chat(7,new ChatRequest(null,"无资料的通关政策",null,false));assertThat(refused.refused()).isTrue();var conversations=new ConversationService(ds);assertThat(conversations.list(7,10)).hasSize(2);assertThat(conversations.messages(7,response.conversationId())).hasSize(2).anySatisfy(message->assertThat(message.citations()).singleElement().satisfies(citation->{assertThat(citation.documentId()).isEqualTo("10");assertThat(citation.documentVersion()).isEqualTo(1);assertThat(citation.sourceUpdatedAt()).isEqualTo(evidence.sourceUpdatedAt());}));conversations.feedback(7,new FeedbackRequest(response.messageId(),true,"有帮助"));conversations.feedback(7,new FeedbackRequest(response.messageId(),false,"需改进"));assertThatThrownBy(()->conversations.messages(8,response.conversationId())).isInstanceOf(BusinessException.class);assertThatThrownBy(()->conversations.messages(7,"bad")).isInstanceOf(BusinessException.class);var eval=governance.addCase(new SaveEvaluationCaseRequest("POLICY","政策是什么","海关政策",null,false,true),9);assertThat(eval.enabled()).isTrue();assertThat(governance.setCaseEnabled(eval.id(),false).enabled()).isFalse();assertThat(governance.setCaseEnabled(eval.id(),true).enabled()).isTrue();assertThatThrownBy(()->governance.setCaseEnabled("bad",true)).isInstanceOf(BusinessException.class);assertThatThrownBy(()->governance.setCaseEnabled("999999",true)).isInstanceOf(BusinessException.class);var evaluation=new AiEvaluationService(ds,chat);assertThat(evaluation.summary().feedback()).isEqualTo(1);assertThat(evaluation.run(7)).singleElement().satisfies(x->assertThat(x.passed()).isTrue());var jdbc=new JdbcTemplate(ds);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM ai_evaluation_run",Integer.class)).isEqualTo(1);}}}
